INSERT OR REPLACE INTO notes (slug, category, title, content, parent_slug, sort_order, updated_at) VALUES ('电路基础/电是什么？？', 'synth', '电是什么？？', '<h1>电是什么？？</h1><div>首先我们需要复习一下高中学过的物理知识，我们知道世界上的物质都是由原子（atom）组成的，在原子的中心有一个原子核（atomic nucleus），质量占据了原子的99.9%以上。原子核由带正电荷的质子（proton）和不带电荷的中子（neutron）组成，在原子核的外围是在不断绕着原子核高速运动的电子（electron），电子带负电荷。原子不带电，电子带的负电荷和质子带的正电荷相等，原子呈电中性，但可以通过得到电子或者失去电子成为阴离子或者阳离子，原子的内部结构图如下：</div><div contenteditable="false" data-resizable="" class="img-light" style="margin: 16px auto; resize: both; max-width: 100%; min-width: 40px; min-height: 20px; text-align: center; width: 311px; height: 216px;"><img src="data:image/png;base64," style="pointer-events: none;"></div>这里有一个关键的概念：电荷。电荷不是一种物质，电荷是一种性质，标志物质中电子数量的多少，用字母Q表示，单位为C（库仑）。电子在原子核外分层运动，每一层最大的电子数是固定的，最内层是2个电子，第二层是八个，第三层也是八个，最外层为价电子层，其中的电子是价电子，价电子的数量决定了原子的化学性质，如果价电子层是满的，则原子性质最稳定。<div>电荷遵循电荷守恒定律，即电荷不能被创生，也不能被消灭，电荷只能移动。电流指的就是电路中电荷的移动。<br><div data-resizable="" class="img-dark" style="display: block; margin: 16px auto; resize: both; max-width: 100%; min-width: 40px; min-height: 20px;"><img src="data:image/png;base64," style="pointer-events: none;"></div><br>
<p></p></div>', '电路基础', 0, 1783837718124);
